<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,shallowReactive,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSession} from '../../session'
import {ApiError} from '../../api'
import {ObjectLease} from '../../object-lease'
import {ownerOf,stockTransport,canManageStock,id,uuid} from './stock-client'
import {createManagerCatalog,type StockWarehouse} from './stock-catalog'
import {ExecutionWork,executionBase,parseOrder,executionState,retainedExecutions,type ExecutionOrder,type ExecutionAction} from './execution-work'
const auth=useSession(),route=useRoute(),router=useRouter(),warehouse=ref(''),approval=ref(''),warehousePage=ref(1),confirmed=ref(false),quantities=reactive<Record<string,string>>({}),tick=ref(0),orderMissing=ref(false)
let alive=true
const engineering=computed(()=>route.path.startsWith('/stock/engineering')),target=computed(()=>({engineering:engineering.value,warehouseId:String(route.params.warehouseId??''),orderId:String(route.params.orderId??'')})),hasTarget=computed(()=>uuid(target.value.orderId)&&(engineering.value||id(target.value.warehouseId))),identity=computed(()=>JSON.stringify(ownerOf(auth))),context=()=>JSON.stringify([identity.value,route.fullPath]),warehouseContext=()=>context()+':'+warehousePage.value,wire=stockTransport(auth,()=>alive)
const warehouses=reactive(new ObjectLease<{items:StockWarehouse[];total:number}>(auth,warehouseContext,async()=>{const stamp=warehouseContext(),r=await createManagerCatalog(wire,()=>warehouseContext()===stamp).warehouses(warehousePage.value);return r}))
const order=reactive(new ObjectLease<ExecutionOrder>(auth,context,async()=>{if(!hasTarget.value)throw Error('请选择授权仓库和批准申请');const t={...target.value},stamp=context();orderMissing.value=false;try{return parseOrder(await wire.send<ExecutionOrder>('GET',executionBase(t)+'/orders/'+t.orderId,undefined,()=>context()===stamp),t)}catch(e){if(alive&&context()===stamp&&e instanceof ApiError&&e.status===404)orderMissing.value=true;throw e}}))
const warehouseAuthorized=computed(()=>!engineering.value&&!!warehouses.value?.items.some(w=>w.id===target.value.warehouseId)),readAuthorized=computed(()=>engineering.value?!!order.value:warehouseAuthorized.value&&!!order.value),writeAllowed=(action:ExecutionAction)=>!!ownerOf(auth)&&(engineering.value?action==='uses'&&!!order.value&&auth.identity!.permissions.includes('ticket.record'):action!=='uses'&&canManageStock(auth.identity)&&warehouseAuthorized.value&&(action==='reserve'||!!order.value))
const work=shallowReactive(new ExecutionWork(wire,()=>ownerOf(auth),writeAllowed,o=>reactive(o),()=>crypto.randomUUID(),e=>{if(e instanceof ApiError&&[401,403,503].includes(e.status)){order.clear('当前对象权限或依赖无法确认，请重新查询。');orderMissing.value=false;confirmed.value=false}}))
const available=computed<ExecutionAction[]>(()=>{void tick.value;if(!hasTarget.value||!confirmed.value)return[];const o=order.value;if(engineering.value)return o?.state==='ISSUED'&&writeAllowed('uses')?['uses']:[];if(!warehouseAuthorized.value||!canManageStock(auth.identity))return[];if(!o)return[];if(['WAITING_STOCK','EXPIRED'].includes(o.state))return['reserve'];if(o.state==='RESERVED')return o.expiresAt&&Date.parse(o.expiresAt)>Date.now()?['issue']:[];return o.state==='ISSUED'?['return']:[]})
const recoveries=computed(()=>{void tick.value;const o=ownerOf(auth);return o?Array.from(retainedExecutions.entries()).flatMap(([key,op])=>{const [tenant,actor,lane,orderId]=JSON.parse(key) as string[];return tenant===o.tenant&&actor===o.actor&&(lane==='engineering')===engineering.value?[{key:op.key,path:lane==='engineering'?'/stock/engineering/orders/'+orderId:'/stock/warehouses/'+lane+'/orders/'+orderId}]:[]}):[]})
const actionName=(a:ExecutionAction)=>({reserve:'整单预留',issue:'整单领用',uses:'登记消耗',return:'原单退回'}[a])
function clearInputs(){confirmed.value=false;for(const k of Object.keys(quantities))delete quantities[k]}
async function refresh(){clearInputs();if(hasTarget.value)await order.refresh()}
async function open(){if(!uuid(approval.value)||!engineering.value&&!id(warehouse.value))return;await router.push(engineering.value?'/stock/engineering/orders/'+approval.value:'/stock/warehouses/'+warehouse.value+'/orders/'+approval.value)}
async function start(action:ExecutionAction,initial=false){if(!confirmed.value||!writeAllowed(action)||!initial&&!available.value.includes(action))return;try{const lines=action==='uses'||action==='return'?Object.entries(quantities).filter(([,v])=>v&&v!=='0').map(([partId,quantity])=>({partId,quantity})):undefined;if(lines&&lines.some(l=>!order.value?.lines.some(x=>x.partId===l.partId&&id(l.quantity)&&BigInt(l.quantity)<=BigInt(x.issued)-BigInt(x.used)-BigInt(x.returned))))throw Error('数量超过原单尚未记账数量');await work.start(action,initial?'0':order.value!.version,lines);confirmed.value=false}catch(e){work.message=e instanceof Error?e.message:'命令无效'}}
function next(){work.next();void refresh()}
async function initialize(){if(!engineering.value)await warehouses.refresh();if(hasTarget.value)await refresh()}
watch(()=>[identity.value,route.fullPath],()=>{work.unbind();clearInputs();orderMissing.value=false;order.clear();warehouses.clear();warehouse.value='';approval.value='';if(hasTarget.value)work.bind(target.value);void initialize()},{immediate:true,flush:'sync'})
function visibility(){clearInputs();if(document.visibilityState==='hidden'){order.clear();warehouses.clear()}else void initialize()}
document.addEventListener('visibilitychange',visibility)
let last=Date.now();const timer=setInterval(()=>{tick.value++;warehouses.expire();order.expire();if(Date.now()-last>=25000){last=Date.now();if(document.visibilityState!=='hidden')void initialize()}},1000)
onBeforeUnmount(()=>{alive=false;work.dispose();warehouses.dispose();order.dispose();clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
<section class="page-heading"><h1>{{engineering?'工程师备件消耗':'库存执行'}}</h1><p>预留不扣现存量；领用只扣一次；消耗记账不再扣库存；退回仅限原单尚未消耗数量。</p></section>
<section class="panel"><h2>当前授权执行单</h2><p>执行单使用已批准备件申请 UUID；输入引用不代表批准或取得权限，服务端逐次核验当前责任和轮次。</p>
<template v-if="!engineering"><p v-if="warehouses.error" role="alert">{{warehouses.error}}</p><label for="execution-warehouse">授权仓库</label><select id="execution-warehouse" v-model="warehouse" :disabled="warehouses.busy"><option value="">请选择仓库</option><option v-for="w in warehouses.value?.items" :key="w.id" :value="w.id">{{w.name}}</option></select><button :disabled="warehousePage<=1||warehouses.busy" @click="warehousePage--;warehouses.clear();warehouses.refresh()">上一页仓库</button><button :disabled="!warehouses.value||warehousePage*20>=warehouses.value.total||warehouses.busy" @click="warehousePage++;warehouses.clear();warehouses.refresh()">下一页仓库</button></template>
<label for="execution-approval">批准申请 UUID</label><input id="execution-approval" v-model="approval" autocomplete="off"><button :disabled="!uuid(approval)||!engineering&&!warehouse" @click="open">查询执行单</button><RouterLink to="/approvals/parts">查找备件申请</RouterLink>
</section>
<section v-if="recoveries.length" class="panel"><h2>本账号原执行恢复</h2><p v-for="r in recoveries" :key="r.key"><RouterLink :to="r.path">恢复原UUID {{r.key}}</RouterLink></p></section>
<section v-if="hasTarget" class="panel"><p>申请 {{target.orderId}}<span v-if="!engineering"> · 仓库 {{target.warehouseId}}</span></p><button :disabled="order.busy" @click="refresh">重新查询当前执行单</button><p v-if="order.busy" role="status">核验当前权限与执行单…</p><p v-if="order.error" role="alert">{{order.error}}。未观察到不等于没有执行，原操作请单独查询。</p>
<template v-if="readAuthorized&&order.value"><h2>服务端当前状态：{{executionState(order.value.state)}}</h2><p>当前版本 {{order.value.version}}<span v-if="order.value.expiresAt"> · 预留截止 {{order.value.expiresAt}}</span></p><p v-if="order.value.state==='RESERVED'">同仓整单预留；领用须在服务端截止前且具备权威免费/付费资格，失败不代表已领用。</p><p v-if="['ACCOUNTED','RETURNED'].includes(order.value.state)">仅本执行单数量已记账；不表示所有批准来源或全部备件清理完成，也不表示工单可关闭。</p>
<div class="table-wrap"><table><thead><tr><th>原单备件</th><th>批准</th><th>领用</th><th>消耗</th><th>退回</th><th>尚未记账</th><th v-if="order.value.state==='ISSUED'">本次{{engineering?'消耗':'退回'}}数量</th></tr></thead><tbody><tr v-for="l in order.value.lines" :key="l.partId"><td>{{l.partId}}</td><td>{{l.quantity}}</td><td>{{l.issued}}</td><td>{{l.used}}</td><td>{{l.returned}}</td><td>{{(BigInt(l.issued)-BigInt(l.used)-BigInt(l.returned)).toString()}}</td><td v-if="order.value.state==='ISSUED'"><input v-model="quantities[l.partId]" :aria-label="'本次数量 '+l.partId" inputmode="numeric" :disabled="!!work.operation||work.busy" placeholder="不填写则不操作"></td></tr></tbody></table></div></template>
<label v-if="!work.operation&&(readAuthorized||warehouseAuthorized)"><input v-model="confirmed" type="checkbox">确认本次执行目标与数量，服务端当前权限、批准来源和执行条件仍须核验</label>
<template v-if="!work.operation"><button v-for="a in available" :key="a" :disabled="work.busy" @click="start(a)">{{actionName(a)}}</button><button v-if="!engineering&&warehouseAuthorized&&orderMissing&&!order.value&&confirmed&&canManageStock(auth.identity)" :disabled="work.busy||order.busy" @click="start('reserve',true)">显式按批准申请首次整单预留（版本0）</button></template>
<template v-if="work.operation"><h2>本动作提交结果</h2><p>原UUID {{work.operation.key}} · {{actionName(work.operation.action)}} · {{work.operation.state}}</p><p>查询只核对原结果；不会自动补发或换键。回执不表示全部备件清理。</p><pre v-if="readAuthorized||warehouseAuthorized&&orderMissing">{{work.operation.body}}</pre><button :disabled="work.busy" @click="work.recover()">查询原执行UUID</button><button v-if="work.operation.state==='NOT_OBSERVED'&&writeAllowed(work.operation.action)" :disabled="work.busy" @click="work.recover(false)">显式原UUID原参数继续</button><template v-if="work.operation.receipt&&readAuthorized"><p>历史回执：{{executionState(work.operation.receipt.state)}} · 当时版本 {{work.operation.receipt.version}}</p><p>这是该动作的历史结果，不替代当前状态或全部来源清理结论。</p></template><button v-if="['SUCCEEDED','REJECTED'].includes(work.operation.state)" :disabled="work.busy" @click="next">明确查询当前单并准备下一动作</button></template><p v-if="work.message" role="status">{{work.message}}</p></section>
</template>
<style scoped>label{display:block;margin:12px 0}input:not([type=checkbox]),select{padding:9px;font:inherit;max-width:100%;width:440px;box-sizing:border-box}td input{width:150px!important}button{margin:6px;padding:9px;font:inherit}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.table-wrap{overflow:auto}pre,p{overflow-wrap:anywhere;white-space:pre-wrap}</style>
